    for i in range(1, n):
        if array[i] > array[i - 1]:
            lis_start[i] = lis_start[i - 1] + 1

    # Find the longest increasing subsequence from the end
    lis_end = [1] * n
    for i in range(n - 2, -1, -1):
        if array[i] < array[i + 1]:
            lis_end[i] = lis_end[i + 1] + 1

    # Calculate the maximum number of elements that can be erased
    max_erase = 0
    for i in range(n):
        if i == 0:
            max_erase = max(max_erase, lis_end[i] - 1)
        elif i == n - 1:
            max_erase = max(max_erase, lis_start[i] - 1)
        else:
            max_erase = max(max_erase, lis_start[i - 1] + lis_end[i + 1] - 1)

    return max_erase

