        for i in range(1, len(arr)):
            for j in range(i):
                if arr[i] > arr[j]:
                    lis[i] = max(lis[i], lis[j] + 1)
        return lis

    lis_from_start = longest_increasing_subsequence(array)
    lis_from_end = longest_increasing_subsequence(array[::-1])[::-1]

    max_erase = 0
    for i in range(n):
        max_erase = max(max_erase, lis_from_start[i] + lis_from_end[i] - 1)

    return max_erase

